using System;
using System.Reflection;
using BepInEx;
using BepInEx.Logging;
using HarmonyLib;
using Necro;

// Yes this was generated by Claude. I'm sorry. Comments are best effort (I don't speak C#)

[BepInPlugin("https://github.com/GrArmpit/Necropolis-Arcanist-Animation-Patch", "Arcanist Animation Patch", "0.2")]
public class ArcanistFix : BaseUnityPlugin
{
    internal static ManualLogSource Log;
    void Awake()
    {
        Log = Logger;
        new Harmony("https://github.com/GrArmpit/Necropolis-Arcanist-Animation-Patch").PatchAll();
        Log.LogInfo("Arcanist fix loaded");
    }
}

[HarmonyPatch(typeof(Actor), "GetMoveSet")]
static class PatchGetMoveSet
{
    const string ArcanistBody = "arcanist";
    const string DonorBody = "brute"; // We're using the brute's animations when no arcanist animation exists for now; thief (Blackguard) may be better.
    static bool inFallback;

    static ActorDef GetDef(Actor actor) // Figure out what the actor we're calling is
    {
        var t = Traverse.Create(actor);
        ActorDef def = null;
        if (t.Field("actorDef").FieldExists())
            def = t.Field("actorDef").GetValue<ActorDef>();
        else if (t.Property("actorDef").PropertyExists())
            def = t.Property("actorDef").GetValue<ActorDef>();
        return def;
    }

    static void Prefix(Actor __instance, string moveSet, ref Action<MoveSet> callback) // If a moveset is called, but arcanist doesn't exist, try again but as a brute
    {
        if (inFallback || callback == null) return; // If we're already trying again as someone else, don't do anything

        ActorDef def = GetDef(__instance);
        if (def == null || def.moveSetBody != ArcanistBody) return; // If we're not an arcanist, don't do anything

        Action<MoveSet> original = callback;
        callback = (MoveSet found) =>
        {
            if (found != null) { original(found); return; } // There is an arcanist animation, don't do anything

            // No arcanist animation
            ArcanistFix.Log.LogInfo("No '" + moveSet + "' for " + ArcanistBody + ", using " + DonorBody);
            string saved = def.moveSetBody;
            inFallback = true;
            try // as brute
            {
                def.moveSetBody = DonorBody; // I'm a brute for sure!
                AccessTools.Method(typeof(Actor), "GetMoveSet")
                    .Invoke(__instance, new object[] { moveSet, original }); // retry
            }
            finally
            {
                def.moveSetBody = saved; // I lied I'm an arcanist again
                inFallback = false;
            }
        };
    }
}
